func newPreference() unsafe.Pointer { return unsafe.Pointer(new(notification.Preference)) }

func newNPreference(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]notification.Preference, n)))
}

func ptrPreference(p unsafe.Pointer, c int32) any {
	r := (*notification.Preference)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return &r.DisabledEventTypes
	case 5:
		return (*string)(unsafe.Pointer(&r.DesktopMode))
	case 6:
		return (*string)(unsafe.Pointer(&r.EmailMode))
	case 7:
		return &r.EmailDigest
	case 8:
		return &r.Sound
	case 9:
		return &r.QuietHoursEnabled
	case 10:
		return &r.QuietHoursStart
	case 11:
		return &r.QuietHoursEnd
	case 12:
		return &r.QuietHoursDays
	case 13:
		return &r.QuietHoursAllowUrgent
	case 14:
		return &r.PausedUntil
	case 15:
		return &r.LastDigestAt
	case 16:
		return &r.Version
	case 17:
		return &r.CreatedAt
	case 18:
		return &r.UpdatedAt
	}
	return nil
}

func valuePreference(p unsafe.Pointer, c int32) any {
	r := (*notification.Preference)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.UserID)
	case 4:
		if r.DisabledEventTypes == nil {
			return []string{}
		}
		return r.DisabledEventTypes
	case 5:
		return string(r.DesktopMode)
	case 6:
		return string(r.EmailMode)
	case 7:
		return r.EmailDigest
	case 8:
		return r.Sound
	case 9:
		return r.QuietHoursEnabled
	case 10:
		return r.QuietHoursStart
	case 11:
		return r.QuietHoursEnd
	case 12:
		if r.QuietHoursDays == nil {
			return []int{}
		}
		return r.QuietHoursDays
	case 13:
		return r.QuietHoursAllowUrgent
	case 14:
		if r.PausedUntil == nil {
			return nil
		}
		return *r.PausedUntil
	case 15:
		if r.LastDigestAt == nil {
			return nil
		}
		return *r.LastDigestAt
	case 16:
		return r.Version
	case 17:
		return r.CreatedAt
	case 18:
		return r.UpdatedAt
	}
	return nil
}

