func newPushSubscription() unsafe.Pointer { return unsafe.Pointer(new(notification.PushSubscription)) }

func newNPushSubscription(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]notification.PushSubscription, n)))
}

func ptrPushSubscription(p unsafe.Pointer, c int32) any {
	r := (*notification.PushSubscription)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return &r.Endpoint
	case 5:
		return &r.P256dh
	case 6:
		return &r.Auth
	case 7:
		return &r.UserAgent
	case 8:
		return &r.CreatedAt
	case 9:
		return &r.UpdatedAt
	}
	return nil
}

func valuePushSubscription(p unsafe.Pointer, c int32) any {
	r := (*notification.PushSubscription)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.UserID)
	case 4:
		return r.Endpoint
	case 5:
		return r.P256dh
	case 6:
		return r.Auth
	case 7:
		if r.UserAgent == "" {
			return nil
		}
		return r.UserAgent
	case 8:
		return r.CreatedAt
	case 9:
		return r.UpdatedAt
	}
	return nil
}

